'use client'

import * as React from 'react'
import { GripVertical } from 'lucide-react'
import * as ResizablePrimitive from 'react-resizable-panels'
import { tv, type VariantProps } from 'tailwind-variants'
import { cn } from '../lib/utils'

export type ResizablePanelGroupProps = React.ComponentPropsWithoutRef<
  typeof ResizablePrimitive.Group
> & {
  direction?: 'horizontal' | 'vertical'
  orientation?: 'horizontal' | 'vertical'
}

const ResizablePanelGroup = ({
  className,
  direction = 'horizontal',
  orientation,
  ...props
}: ResizablePanelGroupProps) => {
  const activeOrientation = orientation || direction
  return (
    <ResizablePrimitive.Group
      orientation={activeOrientation}
      className={cn(
        'flex h-full w-full aria-[orientation=vertical]:flex-col',
        className,
      )}
      {...props}
    />
  )
}

const ResizablePanel = ResizablePrimitive.Panel

const resizableHandleVariants = tv({
  base: 'relative flex w-px shrink-0 items-center justify-center bg-border after:absolute after:inset-y-0 after:left-1/2 after:w-4 after:-translate-x-1/2 after:content-[\'\'] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring aria-[orientation=horizontal]:h-px aria-[orientation=horizontal]:w-full aria-[orientation=horizontal]:after:left-0 aria-[orientation=horizontal]:after:h-4 aria-[orientation=horizontal]:after:w-full aria-[orientation=horizontal]:after:translate-x-0 aria-[orientation=horizontal]:after:-translate-y-1/2 [&[aria-orientation=horizontal]>div]:rotate-90 select-none touch-none',
  variants: {
    variant: {
      default: 'bg-border hover:bg-primary/50',
      glass: 'bg-white/20 dark:bg-white/10 hover:bg-white/40 backdrop-blur-md',
      retro: 'bg-foreground border-x border-foreground w-1.5',
      glow: 'bg-primary/40 shadow-[0_0_10px_rgba(168,85,247,0.4)]',
    },
  },
  defaultVariants: {
    variant: 'default',
  },
})

export interface ResizableHandleProps
  extends React.ComponentPropsWithoutRef<typeof ResizablePrimitive.Separator>,
    VariantProps<typeof resizableHandleVariants> {
  withHandle?: boolean
}

const ResizableHandle = ({
  withHandle,
  variant = 'default',
  className,
  ...props
}: ResizableHandleProps) => (
  <ResizablePrimitive.Separator
    className={cn(resizableHandleVariants({ variant }), className)}
    {...props}
  >
    {withHandle && (
      <div className="z-10 flex h-4 w-3 items-center justify-center rounded-xs border border-border bg-card text-muted-foreground shadow-xs pointer-events-none">
        <GripVertical className="h-2.5 w-2.5" />
      </div>
    )}
  </ResizablePrimitive.Separator>
)

export { ResizablePanelGroup, ResizablePanel, ResizableHandle }
